--

CREATE TABLE `rescates` (
  `id` int(11) NOT NULL COMMENT 'Identificador unico autoincremental',
  `fecha` date NOT NULL COMMENT 'Fecha en que se realizo el rescate o mantenimiento',
  `folio_interno` varchar(30) DEFAULT NULL COMMENT 'Folio interno SITIC - enlace con ventas_reporte.id_docto_cargo',
  `tipo` enum('RESCATE','MTTO') NOT NULL DEFAULT 'RESCATE' COMMENT 'RESCATE: unidad varada en carretera | MTTO: mantenimiento programado',
  `destino` varchar(120) DEFAULT NULL COMMENT 'Ciudad o lugar al que se envio el material',
  `item` varchar(60) DEFAULT NULL COMMENT 'Numero de parte o SKU del articulo enviado',
  `descripcion` text DEFAULT NULL COMMENT 'Descripcion completa del articulo segun catalogo',
  `cantidad_entregada` decimal(10,4) DEFAULT 0.0000 COMMENT 'Piezas enviadas al destino',
  `cantidad_devuelta` decimal(10,4) DEFAULT 0.0000 COMMENT 'Piezas devueltas al almacen',
  `cantidad_usada` decimal(10,4) DEFAULT 0.0000 COMMENT 'Piezas efectivamente utilizadas en la reparacion',
  `cantidad_pendiente` decimal(10,4) DEFAULT 0.0000 COMMENT 'Piezas pendientes de devolucion o cobro',
  `status_bisonte` varchar(150) DEFAULT NULL COMMENT 'Estado segun Bisonte: VALE ENTREGADO POR BISONTE | SE REGRESA MATERIAL | PENDIENTE',
  `status_kw` varchar(150) DEFAULT NULL COMMENT 'Estado KW: Devuelta | Facturada | Impresa | Parcialmente Devuelta | Parcialmente Devuelta y Parcialmente Facturada | Parcialmente Facturada | Sin Imprimir',
  `tecnico` varchar(100) DEFAULT NULL COMMENT 'Nombre del tecnico responsable del rescate o mtto',
  `unidad` varchar(50) DEFAULT NULL COMMENT 'Numero economico de la unidad vehicular atendida (ej. T-691)',
  `bisonte` varchar(100) DEFAULT NULL COMMENT 'Nombre del representante Bisonte responsable',
  `kw` varchar(100) DEFAULT NULL COMMENT 'Nombre del vendedor KW responsable (ej. MARIO RICO, YONA COBOS)',
  `vales` varchar(200) DEFAULT NULL COMMENT 'Numero(s) de vale(s) Bisonte, separados por guion si son varios',
  `observaciones` text DEFAULT NULL COMMENT 'Notas adicionales: cotizaciones, facturas, pagos, devoluciones',
  `created_at` timestamp NULL DEFAULT current_timestamp() COMMENT 'Fecha de creacion del registro en el sistema',
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT 'Fecha de ultima modificacion del registro'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Seguimiento de rescates y mantenimientos - Bisonte SLP / Consigna Kenworth';

